using EduCenterManagement.Data;using EduCenterManagement.Enums;using EduCenterManagement.ViewModels.ParentChildren;using Microsoft.EntityFrameworkCore;namespace EduCenterManagement.Repositories;public sealed class ParentChildrenRepository(ApplicationDbContext db):IParentChildrenRepository{public async Task<ParentChildrenViewModel?> GetChildrenAsync(int p,CancellationToken ct=default){var parent=await db.ParentProfiles.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==p,ct);if(parent is null)return null;var children=await db.ParentStudentLinks.AsNoTracking().Where(x=>x.ParentId==p&&x.Status==ParentStudentLinkStatus.Accepted).Select(x=>new ChildItemViewModel{Id=x.StudentId,Name=x.Student.FullName,ClassCount=db.Enrollments.Count(e=>e.StudentId==x.StudentId&&e.Status==EnrollmentStatus.Confirmed)}).ToListAsync(ct);return new(){LinkingCode=parent.LinkingCode,PendingCount=await db.ParentStudentLinks.CountAsync(x=>x.ParentId==p&&x.Status==ParentStudentLinkStatus.Pending,ct),Children=children};}public async Task<ChildDetailsViewModel?> GetDetailsAsync(int p,int s,CancellationToken ct=default){if(!await db.ParentStudentLinks.AnyAsync(x=>x.ParentId==p&&x.StudentId==s&&x.Status==ParentStudentLinkStatus.Accepted,ct))return null;var st=await db.StudentProfiles.AsNoTracking().SingleAsync(x=>x.Id==s,ct);var classes=await db.Enrollments.AsNoTracking().Where(x=>x.StudentId==s&&x.Status==EnrollmentStatus.Confirmed).Select(x=>new{x.Class.Id,x.Class.Name,Subject=x.Class.Subject.Name,Teacher=x.Class.Teacher==null?"Not assigned":x.Class.Teacher.FullName,Status=x.Class.Status.ToString(),x.Class.StartDate,x.Class.EndDate,Schedule=db.ClassSchedules.Where(q=>q.ClassId==x.ClassId).OrderBy(q=>q.DayOfWeek).Select(q=>q.DayOfWeek+" · "+q.TimeSlot.Name+" ("+q.TimeSlot.StartTime+"–"+q.TimeSlot.EndTime+")").ToList()}).ToListAsync(ct);return new(){Id=s,Name=st.FullName,Classes=classes.Select(x=>new ChildClassViewModel{Id=x.Id,Name=x.Name,Subject=x.Subject,Teacher=x.Teacher,Status=x.Status,StartDate=x.StartDate,EndDate=x.EndDate,Schedule=string.Join(", ",x.Schedule)}).ToList()};}public async Task<AttendancePageViewModel?> GetAttendanceAsync(int parentId,int studentId,int? classId,int page,int pageSize,CancellationToken ct=default){if(!await db.ParentStudentLinks.AnyAsync(x=>x.ParentId==parentId&&x.StudentId==studentId&&x.Status==ParentStudentLinkStatus.Accepted,ct))return null;var student=await db.StudentProfiles.AsNoTracking().SingleAsync(x=>x.Id==studentId,ct);var classes=await db.Enrollments.AsNoTracking().Where(x=>x.StudentId==studentId&&x.Status==EnrollmentStatus.Confirmed).Select(x=>new AttendanceClassOptionViewModel{Id=x.ClassId,Name=x.Class.Name}).ToListAsync(ct);if(classId.HasValue&&!classes.Any(x=>x.Id==classId.Value))return null;var query=db.AttendanceRecords.AsNoTracking().Where(x=>x.StudentId==studentId);if(classId.HasValue)query=query.Where(x=>x.Session.ClassId==classId);var present=await query.CountAsync(x=>x.Status==AttendanceStatus.Present,ct);var absent=await query.CountAsync(x=>x.Status==AttendanceStatus.Absent,ct);var total=await query.CountAsync(ct);var items=await query.OrderByDescending(x=>x.Session.SessionDate).ThenByDescending(x=>x.Session.StartsAt).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new AttendanceRowViewModel{Date=x.Session.SessionDate,Subject=x.Session.Class.Subject.Name,ClassName=x.Session.Class.Name,SessionNumber=x.Session.SessionNumber,Status=x.Status.ToString(),Note=x.Note}).ToListAsync(ct);return new(){StudentId=studentId,StudentName=student.FullName,Items=items,Classes=classes,ClassId=classId,Page=page,TotalPages=Math.Max(1,(int)Math.Ceiling(total/(double)pageSize)),Present=present,Absent=absent};}}